/**
 * Gran-Mestre Integration Engine
 * 
 * Motor central que orquestra a integração entre:
 * - Gran-Mestre (orquestrador)
 * - Superpowers (workflow de desenvolvimento)
 * - Fable Method (verificação adversarial)
 * 
 * Versão: 1.0.0
 */

import { WorkflowDefinition, WorkflowPhase, WorkflowState } from '../workflow/workflow-definition';
import { AgentMapping, AgentRole, AgentLifecycle } from '../agents/agent-mapping';
import { GateSystem, GateMode, GateResult } from '../gates/gate-system';
import { PipelineSelector, PipelineType, PipelineConfig } from '../pipelines/pipeline-selector';
import { SkillRouter, SkillRegistry, SkillPhaseMap } from '../skills/skill-router';
import { MCPCoordinator, MCPHealth } from '../mcp/mcp-coordinator';
import { SecurityModel, Attestation, Rollback } from '../security/security-model';
import { FailureModeRegistry } from '../security/failure-modes';

// ─── Configuração da Integração ────────────────────────────────────────────

export interface IntegrationConfig {
  /** Modo de pipeline: standard (MEDIUM+), cascade (FEATURE), auto (decide automaticamente) */
  mode: 'standard' | 'cascade' | 'auto';

  /** Modo de gate: interativo (A) com aprovação do usuário, autônomo (C) com Héstia como proxy */
  gateMode: 'interactive' | 'autonomous';

  /** Nível de segurança: standard (básico), max (todos os checks) */
  securityLevel: 'standard' | 'max';

  /** Máximo de tentativas por fase antes de escalar */
  maxRetriesPerPhase?: number;

  /** Timeout por fase em minutos */
  phaseTimeoutMinutes?: number;

  /** Habilitar observabilidade OTel */
  enableObservability?: boolean;

  /** Diretório de trabalho */
  workDir?: string;
}

export const DEFAULT_CONFIG: IntegrationConfig = {
  mode: 'auto',
  gateMode: 'interactive',
  securityLevel: 'max',
  maxRetriesPerPhase: 2,
  phaseTimeoutMinutes: 30,
  enableObservability: true,
  workDir: process.cwd(),
};

// ─── Resultado da Execução ─────────────────────────────────────────────────

export interface ExecutionResult {
  /** Status final do pipeline */
  status: 'success' | 'partial' | 'failed' | 'escalated';

  /** Pipeline utilizado */
  pipeline: PipelineType;

  /** Fases completadas */
  completedPhases: WorkflowPhase[];

  /** Fase que falhou (se houver) */
  failedPhase?: WorkflowPhase;

  /** Resultados dos gates */
  gateResults: GateResult[];

  /** Artefatos gerados */
  artifacts: {
    spec?: string;
    plan?: string;
    code?: string;
    review?: string;
    attestation?: string;
  };

  /** Métricas de observabilidade */
  metrics: {
    totalDurationMs: number;
    phaseDurationsMs: Record<string, number>;
    retryCounts: Record<string, number>;
    agentInvocations: number;
    mcpCalls: number;
  };

  /** Relatório final */
  report: string;
}

// ─── Motor de Integração ───────────────────────────────────────────────────

export class IntegrationEngine {
  private config: IntegrationConfig;
  private workflow: WorkflowDefinition;
  private agentMapping: AgentMapping;
  private gateSystem: GateSystem;
  private pipelineSelector: PipelineSelector;
  private skillRouter: SkillRouter;
  private mcpCoordinator: MCPCoordinator;
  private security: SecurityModel;
  private failureModes: FailureModeRegistry;

  private state: WorkflowState;
  private startTime: number = 0;
  private agentInvocationCount: number = 0;
  private mcpCallCount: number = 0;

  constructor(config: Partial<IntegrationConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };

    // Inicializar componentes
    this.workflow = new WorkflowDefinition();
    this.agentMapping = new AgentMapping();
    this.gateSystem = new GateSystem(this.config.gateMode);
    this.pipelineSelector = new PipelineSelector();
    this.skillRouter = new SkillRouter();
    this.mcpCoordinator = new MCPCoordinator();
    this.security = new SecurityModel(this.config.securityLevel);
    this.failureModes = new FailureModeRegistry();

    // Estado inicial
    this.state = this.workflow.createInitialState();
  }

  /**
   * Ponto de entrada principal — executa o pipeline completo
   */
  async execute(request: {
    task: string;
    context?: Record<string, unknown>;
    existingPlan?: string;
    existingSpec?: string;
  }): Promise<ExecutionResult> {
    this.startTime = Date.now();

    // ── FASE 0: Fit Gate (antes de classificar) ──
    const fitGateResult = await this.executeFitGate(request);
    if (fitGateResult.action !== 'pipeline') {
      return this.buildResult({
        status: 'partial',
        gateResults: [fitGateResult.gateResult],
        report: fitGateResult.report,
      });
    }

    // ── Classificar Complexidade ──
    const complexity = this.classifyComplexity(request.task, request.context);

    // ── Selecionar Pipeline ──
    const pipeline = this.pipelineSelector.select(
      complexity,
      this.config.mode,
      request.existingPlan,
      request.existingSpec,
    );

    // ── Executar Pipeline ──
    if (pipeline.type === 'standard') {
      return this.executeStandardPipeline(request, complexity);
    } else {
      return this.executeCascadePipeline(request, complexity);
    }
  }

  // ── Pipeline Padrão (MEDIUM+) ──────────────────────────────────────────

  private async executeStandardPipeline(
    request: { task: string; context?: Record<string, unknown>; existingPlan?: string },
    complexity: string,
  ): Promise<ExecutionResult> {
    const gateResults: GateResult[] = [];
    const artifacts: ExecutionResult['artifacts'] = {};
    const phaseDurations: Record<string, number> = {};
    const retryCounts: Record<string, number> = {};

    // ── Step 1: Prometheus (Planejamento) ──
    const planStart = Date.now();
    this.state.currentPhase = 'discovery';

    const planSkills = this.skillRouter.getSkillsForPhase('discovery', 'standard');
    await this.invokeSkills(planSkills);

    const planResult = await this.invokeAgent('prometheus', {
      task: request.task,
      context: request.context,
      existingPlan: request.existingPlan,
    });
    artifacts.plan = planResult.output;
    phaseDurations['discovery'] = Date.now() - planStart;

    // ── Gate 1: Validação do Plano ──
    const gate1 = await this.gateSystem.evaluate('plan-validation', {
      plan: artifacts.plan,
      task: request.task,
    });
    gateResults.push(gate1);

    if (!gate1.passed) {
      // 3-Strike Protocol
      retryCounts['discovery'] = (retryCounts['discovery'] || 0) + 1;
      if (retryCounts['discovery']! < (this.config.maxRetriesPerPhase || 2)) {
        return this.executeStandardPipeline(request, complexity);
      }
      return this.buildResult({
        status: 'escalated',
        failedPhase: 'discovery',
        gateResults,
        artifacts,
        report: `Gate 1 falhou após ${retryCounts['discovery']} tentativas: ${gate1.reason}`,
      });
    }

    // ── Step 2: Héstia (Validação do Plano) ──
    const validateStart = Date.now();
    this.state.currentPhase = 'planning';

    const validateSkills = this.skillRouter.getSkillsForPhase('planning', 'standard');
    await this.invokeSkills(validateSkills);

    const validateResult = await this.invokeAgent('hestia', {
      plan: artifacts.plan,
      task: request.task,
    });
    phaseDurations['planning'] = Date.now() - validateStart;

    // ── SHA Attestation ──
    if (this.config.securityLevel === 'max') {
      const sha = await this.security.attestPlan(artifacts.plan);
      artifacts.attestation = sha;
    }

    // ── Step 3: Atlas (Execução) ──
    const execStart = Date.now();
    this.state.currentPhase = 'execution';

    const execSkills = this.skillRouter.getSkillsForPhase('execution', 'standard');
    await this.invokeSkills(execSkills);

    // Snapshot para rollback
    const preExecSHA = await this.security.snapshotGit();

    const execResult = await this.invokeAgent('atlas', {
      plan: artifacts.plan,
      task: request.task,
      context: request.context,
    });
    artifacts.code = execResult.output;
    phaseDurations['execution'] = Date.now() - execStart;

    // ── Step 4: Atena/Hephaestus (Revisão) — apenas COMPLEX+ ──
    if (complexity === 'COMPLEX' || complexity === 'CRITICAL') {
      const reviewStart = Date.now();
      this.state.currentPhase = 'review';

      const reviewSkills = this.skillRouter.getSkillsForPhase('review', 'standard');
      await this.invokeSkills(reviewSkills);

      const reviewResult = await this.invokeAgent('atena', {
        code: artifacts.code,
        plan: artifacts.plan,
        task: request.task,
      });
      artifacts.review = reviewResult.output;
      phaseDurations['review'] = Date.now() - reviewStart;
    }

    // ── Step 5: Fable-Judge (Verificação Adversarial) ──
    this.state.currentPhase = 'delivery';

    const judgeResult = await this.invokeFableJudge({
      task: request.task,
      plan: artifacts.plan,
      code: artifacts.code,
      review: artifacts.review,
    });
    gateResults.push(judgeResult);

    // ── Step 6: Memória Cerebral ──
    await this.ingestToMemory({
      task: request.task,
      artifacts,
      gateResults,
      metrics: {
        phaseDurations,
        retryCounts,
      },
    });

    return this.buildResult({
      status: judgeResult.passed ? 'success' : 'partial',
      completedPhases: ['discovery', 'planning', 'execution', 'review', 'delivery'],
      gateResults,
      artifacts,
      report: this.generateReport(artifacts, gateResults, phaseDurations, retryCounts),
    });
  }

  // ── Pipeline em Cascata (FEATURE) ───────────────────────────────────────

  private async executeCascadePipeline(
    request: { task: string; context?: Record<string, unknown>; existingPlan?: string; existingSpec?: string },
    complexity: string,
  ): Promise<ExecutionResult> {
    const gateResults: GateResult[] = [];
    const artifacts: ExecutionResult['artifacts'] = {};
    const phaseDurations: Record<string, number> = {};
    const retryCounts: Record<string, number> = {};

    // ══════════════════════════════════════════════════════════════════════
    // FASE 1 — Descoberta (27B): Prometheus → Brainstorming → GATE 1
    // ══════════════════════════════════════════════════════════════════════
    const f1Start = Date.now();
    this.state.currentPhase = 'discovery';

    // Superpowers: Brainstorming skill
    const brainstormSkills = this.skillRouter.getSkillsForPhase('discovery', 'cascade');
    await this.invokeSkills(brainstormSkills);

    // Gran-Mestre: Prometheus agent
    const discoveryResult = await this.invokeAgent('prometheus', {
      task: request.task,
      context: request.context,
    });

    // Superpowers: Explorar contexto do projeto, fazer perguntas, propor abordagens
    // (executado pelo brainstorming skill via skill router)

    phaseDurations['discovery'] = Date.now() - f1Start;

    // GATE 1: Validação de Descoberta
    const gate1 = await this.gateSystem.evaluate('discovery-validation', {
      task: request.task,
      discovery: discoveryResult.output,
      approaches: discoveryResult.approaches,
    });
    gateResults.push(gate1);

    if (!gate1.passed) {
      retryCounts['discovery'] = (retryCounts['discovery'] || 0) + 1;
      if (retryCounts['discovery']! < (this.config.maxRetriesPerPhase || 2)) {
        return this.executeCascadePipeline(request, complexity);
      }
      return this.buildResult({
        status: 'escalated',
        failedPhase: 'discovery',
        gateResults,
        artifacts,
        report: `Gate 1 falhou: ${gate1.reason}`,
      });
    }

    // ══════════════════════════════════════════════════════════════════════
    // FASE 2 — Contrato (27B): Spec Writer → Héstia → GATE 2
    // ══════════════════════════════════════════════════════════════════════
    const f2Start = Date.now();
    this.state.currentPhase = 'contract';

    // Superpowers: Writing-Plans (spec writing)
    const specSkills = this.skillRouter.getSkillsForPhase('contract', 'cascade');
    await this.invokeSkills(specSkills);

    // Héstia valida o spec
    const specResult = await this.invokeAgent('hestia', {
      discovery: discoveryResult.output,
      spec: request.existingSpec,
    });
    artifacts.spec = specResult.output;
    phaseDurations['contract'] = Date.now() - f2Start;

    // GATE 2: Validação de Contrato
    const gate2 = await this.gateSystem.evaluate('contract-validation', {
      spec: artifacts.spec,
      task: request.task,
      discovery: discoveryResult.output,
    });
    gateResults.push(gate2);

    if (!gate2.passed) {
      retryCounts['contract'] = (retryCounts['contract'] || 0) + 1;
      if (retryCounts['contract']! < (this.config.maxRetriesPerPhase || 2)) {
        return this.executeCascadePipeline(request, complexity);
      }
      return this.buildResult({
        status: 'escalated',
        failedPhase: 'contract',
        gateResults,
        artifacts,
        report: `Gate 2 falhou: ${gate2.reason}`,
      });
    }

    // ══════════════════════════════════════════════════════════════════════
    // FASE 3 — Plano (27B): Plan Writer → Héstia → GATE 3 → SHA
    // ══════════════════════════════════════════════════════════════════════
    const f3Start = Date.now();
    this.state.currentPhase = 'planning';

    // Superpowers: Writing-Plans skill
    const planSkills = this.skillRouter.getSkillsForPhase('planning', 'cascade');
    await this.invokeSkills(planSkills);

    // Héstia valida o plano
    const planResult = await this.invokeAgent('hestia', {
      spec: artifacts.spec,
      discovery: discoveryResult.output,
    });
    artifacts.plan = planResult.output;
    phaseDurations['planning'] = Date.now() - f3Start;

    // GATE 3: Validação de Plano
    const gate3 = await this.gateSystem.evaluate('plan-validation', {
      plan: artifacts.plan,
      spec: artifacts.spec,
      task: request.task,
    });
    gateResults.push(gate3);

    if (!gate3.passed) {
      retryCounts['planning'] = (retryCounts['planning'] || 0) + 1;
      if (retryCounts['planning']! < (this.config.maxRetriesPerPhase || 2)) {
        return this.executeCascadePipeline(request, complexity);
      }
      return this.buildResult({
        status: 'escalated',
        failedPhase: 'planning',
        gateResults,
        artifacts,
        report: `Gate 3 falhou: ${gate3.reason}`,
      });
    }

    // SHA Attestation (salvar integridade do plano)
    if (this.config.securityLevel === 'max') {
      const sha = await this.security.attestPlan(artifacts.plan);
      artifacts.attestation = sha;
    }

    // ══════════════════════════════════════════════════════════════════════
    // FASE 4 — Execução (30B): Atlas (supervisor) + Implementer (TDD) + Code Reviewer
    // ══════════════════════════════════════════════════════════════════════
    const f4Start = Date.now();
    this.state.currentPhase = 'execution';

    // Superpowers: Subagent-Driven Development (fresh subagent per task + 2-stage review)
    const execSkills = this.skillRouter.getSkillsForPhase('execution', 'cascade');
    await this.invokeSkills(execSkills);

    // Snapshot para rollback
    const preExecSHA = await this.security.snapshotGit();

    // Atlas como supervisor + Implementer subagent (TDD)
    const execResult = await this.invokeAgent('atlas', {
      plan: artifacts.plan,
      spec: artifacts.spec,
      task: request.task,
      context: request.context,
      mode: 'subagent-driven', // Atlas supervisiona, Implementers executam
    });
    artifacts.code = execResult.output;
    phaseDurations['execution'] = Date.now() - f4Start;

    // ══════════════════════════════════════════════════════════════════════
    // FASE 5 — Revisão (30B): Atena (diff total)
    // ══════════════════════════════════════════════════════════════════════
    const f5Start = Date.now();
    this.state.currentPhase = 'review';

    // Superpowers: Verification Before Completion
    const reviewSkills = this.skillRouter.getSkillsForPhase('review', 'cascade');
    await this.invokeSkills(reviewSkills);

    const reviewResult = await this.invokeAgent('atena', {
      code: artifacts.code,
      plan: artifacts.plan,
      spec: artifacts.spec,
      task: request.task,
    });
    artifacts.review = reviewResult.output;
    phaseDurations['review'] = Date.now() - f5Start;

    // ══════════════════════════════════════════════════════════════════════
    // FASE 6 — Entrega (27B): Verification → Héstia → GATE 4 → Memória
    // ══════════════════════════════════════════════════════════════════════
    const f6Start = Date.now();
    this.state.currentPhase = 'delivery';

    // Superpowers: Verification Before Completion (evidência antes de claims)
    const deliverySkills = this.skillRouter.getSkillsForPhase('delivery', 'cascade');
    await this.invokeSkills(deliverySkills);

    // Fable-Judge: Verificação adversarial completa
    const judgeResult = await this.invokeFableJudge({
      task: request.task,
      plan: artifacts.plan,
      code: artifacts.code,
      review: artifacts.review,
      spec: artifacts.spec,
    });
    gateResults.push(judgeResult);

    // Héstia: Validação final
    const finalValidation = await this.invokeAgent('hestia', {
      judgeVerdict: judgeResult,
      artifacts,
      task: request.task,
    });

    // GATE 4: Validação de Entrega
    const gate4 = await this.gateSystem.evaluate('delivery-validation', {
      judgeResult,
      finalValidation,
      artifacts,
      task: request.task,
    });
    gateResults.push(gate4);

    if (!gate4.passed) {
      // Rollback
      if (preExecSHA) {
        await this.security.rollback(preExecSHA);
      }
      return this.buildResult({
        status: 'failed',
        failedPhase: 'delivery',
        gateResults,
        artifacts,
        report: `Gate 4 falhou — rollback executado: ${gate4.reason}`,
      });
    }

    // Twin Check (Fable Method)
    if (this.config.securityLevel === 'max') {
      await this.executeTwinCheck(artifacts.code);
    }

    // Memória Cerebral
    await this.ingestToMemory({
      task: request.task,
      artifacts,
      gateResults,
      metrics: { phaseDurations, retryCounts },
    });

    phaseDurations['delivery'] = Date.now() - f6Start;

    return this.buildResult({
      status: 'success',
      completedPhases: ['discovery', 'contract', 'planning', 'execution', 'review', 'delivery'],
      gateResults,
      artifacts,
      report: this.generateReport(artifacts, gateResults, phaseDurations, retryCounts),
    });
  }

  // ── Métodos Auxiliares ──────────────────────────────────────────────────

  private async executeFitGate(request: { task: string; context?: Record<string, unknown> }): Promise<{
    action: 'pipeline' | 'research' | 'inference' | 'skill';
    gateResult: GateResult;
    report: string;
  }> {
    return this.gateSystem.evaluateFitGate(request.task, request.context);
  }

  private classifyComplexity(task: string, context?: Record<string, unknown>): string {
    // Implementação simplificada — na prática, usa LLM para classificar
    const indicators = {
      steps: (task.match(/(?:passo|step|etapa|fase)/gi) || []).length,
      files: (task.match(/(?:arquivo|file|componente|module)/gi) || []).length,
      security: /(?:segurança|security|auth|deploy|produção)/i.test(task),
      design: /(?:design|arquitetura|sistema|plataforma)/i.test(task),
    };

    if (indicators.steps > 7 || indicators.files > 5 || indicators.design) return 'FEATURE';
    if (indicators.steps > 3 || indicators.files > 2) return 'COMPLEX';
    if (indicators.steps > 1) return 'MEDIUM';
    if (indicators.steps === 1) return 'SIMPLE';
    return 'TRIVIAL';
  }

  private async invokeAgent(role: string, input: Record<string, unknown>): Promise<{
    output: string;
    approaches?: string[];
  }> {
    this.agentInvocationCount++;
    const agent = this.agentMapping.getAgent(role);

    // Log para observabilidade
    if (this.config.enableObservability) {
      this.emitSpan(`agent.${role}`, input);
    }

    // Delegação real para o agente (placeholder — integra com OmO)
    return agent.execute(input);
  }

  private async invokeSkills(skills: string[]): Promise<void> {
    for (const skill of skills) {
      // Invoca skill via Superpowers system
      await this.skillRouter.invoke(skill);
    }
  }

  private async invokeFableJudge(context: {
    task: string;
    plan?: string;
    code?: string;
    review?: string;
    spec?: string;
  }): Promise<GateResult> {
    this.agentInvocationCount++;

    // Executa os 5 passos do fable-judge
    const claims = await this.extractClaims(context);
    const diff = await this.establishDiff();
    const verifications = await this.rerunVerifications(claims);
    const frauds = await this.huntFrauds(claims, diff, verifications);

    return {
      gateName: 'fable-judge',
      passed: frauds.length === 0 && verifications.every(v => v.passed),
      verdict: frauds.length === 0 ? 'VERIFIED' : 'REFUTED',
      claims,
      frauds,
      reason: frauds.length > 0 
        ? `${frauds.length} fraude(s) encontrada(s)` 
        : 'Todas as afirmações verificadas',
    };
  }

  private async extractClaims(context: Record<string, unknown>): Promise<string[]> {
    // Extrai afirmações do relatório/plano
    return [];
  }

  private async establishDiff(): Promise<string> {
    // git diff para estabelecer o que realmente mudou
    return '';
  }

