  private generateReport(
    artifacts: Record<string, unknown>,
    gateResults: GateResult[],
    phaseDurations: Record<string, number>,
    retryCounts: Record<string, number>,
  ): string {
    const lines = [
      '# Relatório de Execução — Gran-Mestre Integration',
      '',
      `## Status: ${this.state.currentPhase === 'delivery' ? '✅ Concluído' : '⚠️ Em progresso'}`,
      '',
      '## Fases Executadas',
      ...Object.entries(phaseDurations).map(([phase, duration]) => 
        `- **${phase}**: ${(duration / 1000).toFixed(1)}s`
      ),
      '',
      '## Gates',
      ...gateResults.map(g => 
        `- **${g.gateName}**: ${g.passed ? '✅ PASS' : '❌ FAIL'} — ${g.reason}`
      ),
      '',
      '## Artefatos',
      ...Object.entries(artifacts).filter(([_, v]) => v).map(([key]) => 
        `- ${key}: ✅ Gerado`
      ),
    ];

    return lines.join('\n');
  }
}

