// ─── Máquina de Estado ─────────────────────────────────────────────────────

export class WorkflowDefinition {
  private phases: Map<WorkflowPhase, PhaseDefinition>;

  constructor() {
    this.phases = new Map();
    for (const phase of WORKFLOW_PHASES) {
      this.phases.set(phase.id, phase);
    }
  }

  createInitialState(): WorkflowState {
    const phaseStatuses = {} as Record<WorkflowPhase, PhaseStatus>;
    for (const phase of WORKFLOW_PHASES) {
      phaseStatuses[phase.id] = 'pending';
    }

    return {
      currentPhase: 'discovery',
      phaseStatuses,
      context: {},
      startedAt: Date.now(),
      phaseStartedAt: Date.now(),
    };
  }

  getPhase(id: WorkflowPhase): PhaseDefinition | undefined {
    return this.phases.get(id);
  }

  getNextPhase(current: WorkflowPhase): WorkflowPhase | null {
    const idx = WORKFLOW_PHASES.findIndex(p => p.id === current);
    if (idx === -1 || idx === WORKFLOW_PHASES.length - 1) return null;
    return WORKFLOW_PHASES[idx + 1].id;
  }

  getDependencies(phase: WorkflowPhase): WorkflowPhase[] {
    return this.phases.get(phase)?.dependencies || [];
  }

  canPhaseSkip(phase: WorkflowPhase): boolean {
    return this.phases.get(phase)?.skippable || false;
  }

  getPhaseSequence(): WorkflowPhase[] {
    return WORKFLOW_PHASES.map(p => p.id);
  }

  validateDependencies(completedPhases: WorkflowPhase[]): WorkflowPhase[] {
    // Retorna fases cujas dependências foram todas completadas
    return WORKFLOW_PHASES
      .filter(p => !completedPhases.includes(p.id))
      .filter(p => p.dependencies.every(dep => completedPhases.includes(dep)))
      .map(p => p.id);
  }
}

