export class AgentMapping {
  private agents: Map<AgentRole, AgentDefinition>;

  constructor() {
    this.agents = new Map();
    for (const agent of AGENT_REGISTRY) {
      this.agents.set(agent.id, agent);
    }
  }

  getAgent(role: string): AgentDefinition | undefined {
    return this.agents.get(role as AgentRole);
  }

  getAgentsForPhase(phase: WorkflowPhase): {
    primary: AgentDefinition[];
    support: AgentDefinition[];
    review: AgentDefinition[];
  } {
    const mapping = AGENT_PHASE_MAP[phase];
    return {
      primary: mapping.primary.map(r => this.agents.get(r)!).filter(Boolean),
      support: mapping.support.map(r => this.agents.get(r)!).filter(Boolean),
      review: mapping.review.map(r => this.agents.get(r)!).filter(Boolean),
    };
  }

  getAgentByFramework(framework: 'gran-mestre' | 'superpowers' | 'fable-method'): AgentDefinition[] {
    return AGENT_REGISTRY.filter(a => a.framework === framework);
  }

  getModelForPhase(phase: WorkflowPhase): AgentTier {
    const agents = this.getAgentsForPhase(phase);
    const allAgents = [...agents.primary, ...agents.support, ...agents.review];

    // Retorna o tier mais alto necessário
    if (allAgents.some(a => a.modelTier === '30B')) return '30B';
    if (allAgents.some(a => a.modelTier === '27B')) return '27B';
    return '8B';
  }
}

