/**
 * Gate System — Gates entre Fases
 * 
 * Implementa o sistema de gates do Gran-Mestre com:
 * - Gate A (interativo): 4 gates, máximo alinhamento com usuário
 * - Gate C (autônomo): Héstia como proxy, escala ao usuário após 2 reprovas
 * 
 * Cada gate é composto por evaluators que verificam critérios específicos.
 */

import { WorkflowPhase } from '../workflow/workflow-definition';

// ─── Tipos ─────────────────────────────────────────────────────────────────

export type GateMode = 'interactive' | 'autonomous';

export interface GateResult {
  gateName: string;
  passed: boolean;

  /** Veredito do fable-judge (se aplicável) */
  verdict?: 'VERIFIED' | 'VERIFIED WITH CAVEATS' | 'REFUTED';

  /** Afirmações verificadas (se aplicável) */
  claims?: string[];

  /** Fraudes encontradas (se aplicável) */
  frauds?: Array<{
    type: string;
    description: string;
    evidence: string;
  }>;

  /** Razão do resultado */
  reason: string;

  /** Evaluators executados */
  evaluatorResults: EvaluatorResult[];

  /** Timestamp */
  timestamp: number;
}

export interface EvaluatorResult {
  name: string;
  passed: boolean;
  message: string;
  evidence?: string;
}

export interface GateDefinition {
  name: string;
  description: string;
  phase: WorkflowPhase;

  /** Evaluators que compõem este gate */
  evaluators: string[];

  /** Se requer aprovação do usuário (modo interativo) */
  requiresUserApproval: boolean;

  /** Máximo de reprovas antes de escalar */
  maxRejectionsBeforeEscalation: number;

  /** Ação ao falhar */
  onFail: 'retry' | 'escalate' | 'rollback' | 'abort';
}

