// ─── Sistema de Gates ──────────────────────────────────────────────────────

export class GateSystem {
  private mode: GateMode;
  private rejections: Map<string, number> = new Map();
  private gateDefinitions: Map<string, GateDefinition>;

  constructor(mode: GateMode = 'interactive') {
    this.mode = mode;
    this.gateDefinitions = new Map();
    for (const gate of GATE_DEFINITIONS) {
      this.gateDefinitions.set(gate.name, gate);
    }
  }

  /**
   * Avalia um gate
   */
  async evaluate(
    gateName: string,
    context: Record<string, unknown>,
  ): Promise<GateResult> {
    const gate = this.gateDefinitions.get(gateName);
    if (!gate) {
      return {
        gateName,
        passed: false,
        reason: `Gate '${gateName}' não encontrado`,
        evaluatorResults: [],
        timestamp: Date.now(),
      };
    }

    // Executar evaluators
    const evaluatorResults: EvaluatorResult[] = [];
    for (const evaluatorName of gate.evaluators) {
      const evaluator = EVALUATORS[evaluatorName];
      if (!evaluator) {
        evaluatorResults.push({
          name: evaluatorName,
          passed: false,
          message: `Evaluator '${evaluatorName}' não encontrado`,
        });
        continue;
      }

      const result = await evaluator(context);
      evaluatorResults.push(result);
    }

    const allPassed = evaluatorResults.every(r => r.passed);
    const passed = allPassed;

    // Modo autônomo: Héstia decide (escalation após maxRejections)
    if (this.mode === 'autonomous' && !passed) {
      const currentRejections = (this.rejections.get(gateName) || 0) + 1;
      this.rejections.set(gateName, currentRejections);

      if (currentRejections >= gate.maxRejectionsBeforeEscalation && gate.maxRejectionsBeforeEscalation > 0) {
        // Escalar ao usuário
        return {
          gateName,
          passed: false,
          reason: `Escalado ao usuário após ${currentRejections} reprovações`,
          evaluatorResults,
          timestamp: Date.now(),
        };
      }
    }

    return {
      gateName,
      passed,
      reason: passed 
        ? 'Todos os evaluators aprovaram'
        : `Evaluators falhados: ${evaluatorResults.filter(r => !r.passed).map(r => r.name).join(', ')}`,
      evaluatorResults,
      timestamp: Date.now(),
    };
  }

  /**
   * Fit Gate — roda antes de classificar complexidade
   */
  async evaluateFitGate(
    task: string,
    context?: Record<string, unknown>,
  ): Promise<{
    action: 'pipeline' | 'research' | 'inference' | 'skill';
    gateResult: GateResult;
    report: string;
  }> {
    // Lógica do Fit Gate (Fable Method)
    // 1. Fontes acessíveis? → pipeline
    // 2. Técnica que modelo não conhece? → research
    // 3. Apenas inferência? → declarar explicitamente
    // 4. Procedimento recorrente? → criar skill

    const gateResult = await this.evaluate('gate-0-fit', { task, ...context });

    return {
      action: 'pipeline',
      gateResult,
      report: 'Fit Gate: fontes acessíveis, prosseguindo com pipeline',
    };
  }

  /**
   * Obter definição de um gate
   */
  getGateDefinition(name: string): GateDefinition | undefined {
    return this.gateDefinitions.get(name);
  }

  /**
   * Obter todos os gates de uma fase
   */
  getGatesForPhase(phase: WorkflowPhase): GateDefinition[] {
    return GATE_DEFINITIONS.filter(g => g.phase === phase);
  }

  /**
   * Verificar modo
   */
  getMode(): GateMode {
    return this.mode;
  }

  /**
   * Contagem de reprovações
   */
  getRejectionCount(gateName: string): number {
    return this.rejections.get(gateName) || 0;
  }
}

/**
 * Gate System — Gates entre Fases
 * 
 * Implementa o sistema de gates do Gran-Mestre com:
 * - Gate A (interativo): 4 gates, máximo alinhamento com usuário
 * - Gate C (autônomo): Héstia como proxy, escala ao usuário após 2 reprovas
 * 
 * Cada gate é composto por evaluators que verificam critérios específicos.
 */

import { WorkflowPhase } from '../workflow/workflow-definition';

