export type GateMode = 'interactive' | 'autonomous';

export interface GateResult {
  gateName: string;
  passed: boolean;

  /** Veredito do fable-judge (se aplicável) */
  verdict?: 'VERIFIED' | 'VERIFIED WITH CAVEATS' | 'REFUTED';

  /** Afirmações verificadas (se aplicável) */
  claims?: string[];

  /** Fraudes encontradas (se aplicável) */
  frauds?: Array<{
    type: string;
    description: string;
    evidence: string;
  }>;

  /** Razão do resultado */
  reason: string;

  /** Evaluators executados */
  evaluatorResults: EvaluatorResult[];

  /** Timestamp */
  timestamp: number;
}

export interface EvaluatorResult {
  name: string;
  passed: boolean;
  message: string;
  evidence?: string;
}

export interface GateDefinition {
  name: string;
  description: string;
  phase: WorkflowPhase;

  /** Evaluators que compõem este gate */
  evaluators: string[];

  /** Se requer aprovação do usuário (modo interativo) */
  requiresUserApproval: boolean;

  /** Máximo de reprovas antes de escalar */
  maxRejectionsBeforeEscalation: number;

  /** Ação ao falhar */
  onFail: 'retry' | 'escalate' | 'rollback' | 'abort';
}

