// ─── Seletor ───────────────────────────────────────────────────────────────

export class PipelineSelector {
  private lastSelected: PipelineType = 'standard';

  /**
   * Seleciona o pipeline baseado na complexidade e configuração
   */
  select(
    complexity: ComplexityLevel,
    mode: 'standard' | 'cascade' | 'auto',
    existingPlan?: string,
    existingSpec?: string,
  ): PipelineConfig {
    // Modo forçado
    if (mode === 'standard') {
      this.lastSelected = 'standard';
      return STANDARD_PIPELINE;
    }
    if (mode === 'cascade') {
      this.lastSelected = 'cascade';
      return CASCADE_PIPELINE;
    }

    // Modo auto: decidir baseado na complexidade
    const routing = ROUTING_TABLE[complexity];

    // Se já existe plano, pular para standard (ou execução direta)
    if (existingPlan && existingSpec) {
      this.lastSelected = 'standard';
      return {
        ...STANDARD_PIPELINE,
        phases: ['execution', 'review', 'delivery'],
        description: 'Plano existente — executando diretamente.',
      };
    }

    // Se existe spec mas não plano
    if (existingSpec && !existingPlan) {
      this.lastSelected = 'standard';
      return {
        ...STANDARD_PIPELINE,
        phases: ['planning', 'execution', 'review', 'delivery'],
        description: 'Spec existente — planejando e executando.',
      };
    }

    // Roteamento padrão
    this.lastSelected = routing.pipeline;
    return routing.pipeline === 'cascade' ? CASCADE_PIPELINE : STANDARD_PIPELINE;
  }

  /**
   * Retorna o último pipeline selecionado
   */
  getLastSelected(): PipelineType {
    return this.lastSelected;
  }

  /**
   * Obtém a config de roteamento para uma complexidade
   */
  getRouting(complexity: ComplexityLevel) {
    return ROUTING_TABLE[complexity];
  }

  /**
   * Verifica se deve pular review para uma complexidade
   */
  shouldSkipReview(complexity: ComplexityLevel): boolean {
    return ROUTING_TABLE[complexity].skipReview;
  }

  /**
   * Obtém máximo de ciclos para uma complexidade
   */
  getMaxCycles(complexity: ComplexityLevel): number {
    return ROUTING_TABLE[complexity].maxCycles;
  }

  /**
   * Lista todas as rotas possíveis
   */
  getAllRoutes() {
    return Object.entries(ROUTING_TABLE).map(([level, config]) => ({
      level: level as ComplexityLevel,
      ...config,
    }));
  }
}

