// ─── Router ────────────────────────────────────────────────────────────────

export class SkillRouter {
  private skills: Map<string, SkillDefinition>;
  private invocationLog: string[] = [];

  constructor() {
    this.skills = new Map();
    for (const skill of SKILL_REGISTRY) {
      this.skills.set(skill.id, skill);
    }
  }

  /**
   * Obtém skills para uma fase e pipeline específicos
   */
  getSkillsForPhase(
    phase: WorkflowPhase,
    pipeline: PipelineType,
  ): string[] {
    const phaseSkills = SKILL_PHASE_MAP[phase] || [];

    return phaseSkills.filter(skillId => {
      const skill = this.skills.get(skillId);
      if (!skill) return false;

      // Filtrar por pipeline
      if (!skill.pipelines.includes(pipeline)) return false;

      return true;
    });
  }

  /**
   * Invoca uma skill (placeholder — integra com Superpowers skill system)
   */
  async invoke(skillId: string): Promise<void> {
    this.invocationLog.push(`${new Date().toISOString()}: ${skillId}`);

    // Na prática, isso invoca a skill via Superpowers system
    // ou carrega o SKILL.md correspondente
  }

  /**
   * Obtém definição de uma skill
   */
  getSkill(id: string): SkillDefinition | undefined {
    return this.skills.get(id);
  }

  /**
   * Obtém todas as skills de um framework
   */
  getSkillsByFramework(framework: SkillFramework): SkillDefinition[] {
    return SKILL_REGISTRY.filter(s => s.framework === framework);
  }

  /**
   * Obtém skills de verificação (gates)
   */
  getVerificationSkills(): SkillDefinition[] {
    return SKILL_REGISTRY.filter(s => s.isVerification);
  }

  /**
   * Log de invocações
   */
  getInvocationLog(): string[] {
    return [...this.invocationLog];
  }

  /**
   * Obtém skills ordenadas por prioridade para uma fase
   */
  getSkillsOrderedByPriority(
    phase: WorkflowPhase,
    pipeline: PipelineType,
  ): SkillDefinition[] {
    const skillIds = this.getSkillsForPhase(phase, pipeline);
    return skillIds
      .map(id => this.skills.get(id)!)
      .filter(Boolean)
      .sort((a, b) => a.priority - b.priority);
  }
}

