// ─── Coordination ──────────────────────────────────────────────────────────

export class MCPCoordinator {
  private servers: Map<string, MCPServer>;
  private callLog: Array<{ server: string; tool: string; timestamp: number; phase: WorkflowPhase }> = [];

  constructor() {
    this.servers = new Map();
    for (const server of MCP_REGISTRY) {
      this.servers.set(server.name, { ...server });
    }
  }

  /**
   * Verifica health de todos os MCPs
   */
  async checkHealth(): Promise<MCPHealthReport> {
    const reports: MCPHealth[] = [];

    for (const [name, server] of this.servers) {
      reports.push({
        server: name,
        status: server.status,
        toolsAvailable: server.tools.length,
        phase: 'health-check',
      });
    }

    return {
      timestamp: Date.now(),
      servers: reports,
      allHealthy: reports.every(r => r.status !== 'error'),
    };
  }

  /**
   * Obtém MCPs disponíveis para uma fase
   */
  getMCPsForPhase(phase: WorkflowPhase): {
    required: MCPServer[];
    recommended: MCPServer[];
    optional: MCPServer[];
  } {
    const config = MCP_PHASE_CONFIG[phase];

    return {
      required: config.required
        .map(name => this.servers.get(name))
        .filter((s): s is MCPServer => Boolean(s && s.status !== 'error')),
      recommended: config.recommended
        .map(name => this.servers.get(name))
        .filter((s): s is MCPServer => Boolean(s && s.status !== 'error')),
      optional: config.optional
        .map(name => this.servers.get(name))
        .filter((s): s is MCPServer => Boolean(s && s.status !== 'error')),
    };
  }

  /**
   * Registra chamada MCP
   */
  logCall(server: string, tool: string, phase: WorkflowPhase): void {
    this.callLog.push({
      server,
      tool,
      timestamp: Date.now(),
      phase,
    });
  }

  /**
   * Obtém log de chamadas
   */
  getCallLog(): typeof this.callLog {
    return [...this.callLog];
  }

  /**
   * Contagem total de chamadas MCP
   */
  getTotalCalls(): number {
    return this.callLog.length;
  }

  /**
   * Verifica se um MCP obrigatório está disponível
   */
  validateRequiredMCPs(phase: WorkflowPhase): { valid: boolean; missing: string[] } {
    const config = MCP_PHASE_CONFIG[phase];
    const missing: string[] = [];

    for (const name of config.required) {
      const server = this.servers.get(name);
      if (!server || server.status === 'error') {
        missing.push(name);
      }
    }

    return {
      valid: missing.length === 0,
      missing,
    };
  }

  /**
   * Obtém resumo de uso por fase
   */
  getUsageByPhase(): Record<WorkflowPhase, number> {
    const usage = {} as Record<WorkflowPhase, number>;
    for (const entry of this.callLog) {
      usage[entry.phase] = (usage[entry.phase] || 0) + 1;
    }
    return usage;
  }
}

