/**
 * Security Model — Modelo de Segurança Combinado
 * 
 * Consolida segurança de todos os três frameworks:
 * 
 * GRAN-MESTRE:
 * - SHA-256 attestation de planos
 * - Git rollback safety protocol
 * - 3-Strike Error Protocol
 * - 2-Action Rule
 * 
 * SUPERPOWERS:
 * - Verification Before Completion (evidência antes de claims)
 * - Two-stage review (spec compliance + code quality)
 * - No code on main without consent
 * 
 * FABLE METHOD:
 * - 18 Failure Modes catalogados
 * - 6 fraudes clássicas (fable-judge)
 * - Twin Check
 * - Artifact Gate
 * - Fit Gate
 */

import { createHash } from 'crypto';
import { execSync } from 'child_process';

// ─── Níveis de Segurança ───────────────────────────────────────────────────

export type SecurityLevel = 'standard' | 'max';

export interface SecurityConfig {
  level: SecurityLevel;
  enableAttestation: boolean;
  enableRollback: boolean;
  enableTwinCheck: boolean;
  enableArtifactGate: boolean;
  maxRollbacksPerPipeline: number;
  enableOTel: boolean;
}

const SECURITY_CONFIGS: Record<SecurityLevel, SecurityConfig> = {
  standard: {
    level: 'standard',
    enableAttestation: false,
    enableRollback: true,
    enableTwinCheck: false,
    enableArtifactGate: false,
    maxRollbacksPerPipeline: 1,
    enableOTel: false,
  },
  max: {
    level: 'max',
    enableAttestation: true,
    enableRollback: true,
    enableTwinCheck: true,
    enableArtifactGate: true,
    maxRollbacksPerPipeline: 1,
    enableOTel: true,
  },
};

// ─── SHA-256 Attestation ───────────────────────────────────────────────────

export class Attestation {
  private attestations: Map<string, { sha256: string; timestamp: number }> = new Map();

  /**
   * Calcula SHA-256 de um plano e armazena
   */
  async attest(content: string, label: string = 'plan'): Promise<string> {
    const sha256 = createHash('sha256').update(content).digest('hex');
    this.attestations.set(label, {
      sha256,
      timestamp: Date.now(),
    });
    return sha256;
  }

  /**
   * Verifica se conteúdo corresponde ao attestation
   */
  verify(content: string, label: string = 'plan'): {
    valid: boolean;
    expected?: string;
    actual: string;
  } {
    const stored = this.attestations.get(label);
    if (!stored) {
      return {
        valid: false,
        actual: createHash('sha256').update(content).digest('hex'),
      };
    }

    const actual = createHash('sha256').update(content).digest('hex');
    return {
      valid: stored.sha256 === actual,
      expected: stored.sha256,
      actual,
    };
  }

  /**
   * Obtém attestation armazenado
   */
  getAttestation(label: string): { sha256: string; timestamp: number } | undefined {
    return this.attestations.get(label);
  }
}

// ─── Git Rollback ──────────────────────────────────────────────────────────

export class Rollback {
  private snapshots: Map<string, { sha: string; timestamp: number }> = new Map();
  private rollbackCount: number = 0;

  /**
   * Captura snapshot do estado atual do git
   */
  async snapshotGit(workDir?: string): Promise<string | null> {
    try {
      const dir = workDir || process.cwd();
      const sha = execSync('git rev-parse HEAD', { cwd: dir, encoding: 'utf-8' }).trim();
      this.snapshots.set('pre-execution', {
        sha,
        timestamp: Date.now(),
      });
      return sha;
    } catch {
      return null; // não é um repo git
    }
  }

  /**
   * Executa rollback para um SHA específico
   */
  async rollback(sha: string, workDir?: string): Promise<{
    success: boolean;
    message: string;
  }> {
    if (this.rollbackCount >= 1) {
      return {
        success: false,
        message: 'Máximo de 1 rollback por pipeline já atingido',
      };
    }

    try {
      const dir = workDir || process.cwd();
      execSync(`git reset --hard ${sha}`, { cwd: dir });
      this.rollbackCount++;
      return {
        success: true,
        message: `Rollback para ${sha} executado com sucesso`,
      };
    } catch (error) {
      return {
        success: false,
        message: `Rollback falhou: ${error}`,
      };
    }
  }

  /**
   * Contagem de rollbacks executados
   */
  getRollbackCount(): number {
    return this.rollbackCount;
  }

  /**
   * Reset contadores (novo pipeline)
   */
  reset(): void {
    this.snapshots.clear();
    this.rollbackCount = 0;
  }
}

// ─── Modelo de Segurança Combinado ─────────────────────────────────────────

export class SecurityModel {
  private config: SecurityConfig;
  private attestation: Attestation;
  private rollback: Rollback;

  constructor(level: SecurityLevel = 'max') {
    this.config = SECURITY_CONFIGS[level];
    this.attestation = new Attestation();
    this.rollback = new Rollback();
  }

  /**
   * Atesta integridade de um plano
   */
  async attestPlan(content: string): Promise<string> {
    if (!this.config.enableAttestation) return '';
    return this.attestation.attest(content, 'plan');
  }

  /**
   * Verifica integridade de um plano
   */
  verifyPlan(content: string): boolean {
    if (!this.config.enableAttestation) return true;
    return this.attestation.verify(content, 'plan').valid;
  }

  /**
   * Captura snapshot git
   */
  async snapshotGit(workDir?: string): Promise<string | null> {
    if (!this.config.enableRollback) return null;
    return this.rollback.snapshotGit(workDir);
  }

  /**
   * Executa rollback
   */
  async rollback(sha: string, workDir?: string) {
    return this.rollback.rollback(sha, workDir);
  }

  /**
   * Verifica se deve executar twin check
   */
  shouldTwinCheck(): boolean {
    return this.config.enableTwinCheck;
  }

  /**
   * Verifica se deve executar artifact gate
   */
  shouldArtifactGate(): boolean {
    return this.config.enableArtifactGate;
  }

  /**
   * Obtém config atual
   */
  getConfig(): SecurityConfig {
    return { ...this.config };
  }
}

