// ─── Hook Integration Class ────────────────────────────────────────────────

export class HookIntegration {
  /**
   * Obtém hooks que disparam para uma fase
   */
  getHooksForPhase(phase: WorkflowPhase): HookPoint[] {
    return HOOK_POINTS_BY_PHASE[phase] || [];
  }

  /**
   * Obtém hooks blocking para uma fase
   */
  getBlockingHooks(phase: WorkflowPhase): HookPoint[] {
    return this.getHooksForPhase(phase).filter(h => h.blocking);
  }

  /**
   * Obtém hooks por tipo
   */
  getHooksByType(type: 'native' | 'ecc' | 'gsd-loop'): HookPoint[] {
    const all: HookPoint[] = [];
    for (const hooks of Object.values(HOOK_POINTS_BY_PHASE)) {
      all.push(...hooks.filter(h => h.type === type));
    }
    return all;
  }

  /**
   * Conta total de hooks por fase
   */
  getHookCounts(): Record<WorkflowPhase, number> {
    const counts = {} as Record<WorkflowPhase, number>;
    for (const [phase, hooks] of Object.entries(HOOK_POINTS_BY_PHASE)) {
      counts[phase as WorkflowPhase] = hooks.length;
    }
    return counts;
  }
}

